from auto_config.generator.gnb.managed_objects.managed_object import ManagedObject


class ClockParamsGenerator(ManagedObject):

    def _prepare_section_content(self, execution_config, *args, **kwargs):

        if self.is_mo_ecpri:
            self.set_parameter('holdOverModeUsed', 'false')
            self.set_parameter('syncMaster', 'true')

        # ASOF
        elif 'smods' in self.enb_ent_config and self.enb_ent_config['smods']['1'].get('prod_code_planned') == "476147A":
            self.set_parameter('sModDN', f"MRBTS-{self.enb_ent_config['id']}/EQM-1/APEQM-1/CABINET-1/SMOD-{self.mo_num}")
            self.set_struct_parameter('syncInputList', 'syncInputPrio', '1')
            self.set_struct_parameter('syncInputList', 'syncInputType', 'internal GNSS receiver')

        else:
            self.set_parameter('sModDN', f"MRBTS-{self.enb_ent_config['id']}/EQM-1/APEQM-1/CABINET-1/SMOD-{self.mo_num}")
            self.set_parameter('outputConfiguration1PpsFHS', 'Disabled')
            self.set_parameter('outputConfigurationFCLK', 'Disabled')

            self.set_syncInputList(execution_config)
            self.set_outputConfiguration1Pps(execution_config)
            self.set_outputConfiguration1PpsBackplane(execution_config)
            self.set_outputConfiguration2M048()

    def set_syncInputList(self, execution_config):

        if self.enb_ent_config['sync'].startswith('top'):
            if self.enb_ent_config['has_freq_sync']:
                sync_input_type = 'TOPF'
            else:
                sync_input_type = 'TOPP'
        elif self.enb_ent_config['sync'].startswith('hub'):
            sync_input_type = '1pps/ToD from Sync Hub Master'
        elif self.mo_num == '1':
            sync_input_type = '1pps/ToD from external GNSS receiver'
        else:
            if execution_config['is_fullrack']:
                sync_input_type = '1pps/ToD from external GNSS receiver'
            else:
                sync_input_type = '1pps/ToD from backplane'

        self.set_struct_parameter('syncInputList', 'syncInputPrio', '1')
        self.set_struct_parameter('syncInputList', 'syncInputType', sync_input_type)

    def set_outputConfiguration1Pps(self, execution_config):
        if self.mo_num == '1':
            self.set_parameter('outputConfiguration1Pps', self.enb_ent_config.get('sync_output_pps', 'EnabledWithBtsInputReference'))
        else:
            if execution_config['is_fullrack']:
                self.set_parameter('outputConfiguration1Pps', 'EnabledWithoutBtsInputReference')
            else:
                self.set_parameter('outputConfiguration1Pps', 'Disabled')

    def set_outputConfiguration1PpsBackplane(self, execution_config):
        if self.enb_ent_config.get('sync_output_pps_backplane') and execution_config['release'] >= 21.7:
            self.set_parameter('outputConfiguration1PpsBackplane', self.enb_ent_config['sync_output_pps_backplane'])
        else:
            self.set_parameter('outputConfiguration1PpsBackplane', 'Disabled')

    def set_outputConfiguration2M048(self):
        if self.enb_ent_config.get('sync_output_2m'):
            self.set_parameter('outputConfiguration2M048', self.enb_ent_config['sync_output_2m'])
        else:
            self.set_parameter('outputConfiguration2M048', 'Disabled')
